import sys, json, random, subprocess
sys.path.insert(0, '/workspace/tests')
from harness import run_raw, check, FAILURES, summary

random.seed(7)

TEMPLATES = ['x', '', "{{b'abc'}}", "{{b'a' * 3 + b'b'[0:1]}}", '<<random_string>>',
             'a<<random_string>>b<<random_string>>', '{{ nope }}', "{{ 'é'[0:1] }}",
             '{{' + 'b\'a\'+' * 40 + "b'a'" + '}}', 'y' * 10, '{{2}}']
FRAME_TYPES = ['headers', 'data', 'datagram', 'sleep', 'bogus']

def rand_frame(depth=0):
    t = random.choice(FRAME_TYPES)
    f = {'Type': t}
    if t == 'headers':
        if random.random() < .5:
            f['headers_kv'] = {('k%d' % i): random.choice(TEMPLATES) for i in range(random.randrange(0, 3))}
        else:
            f['data_to_transfered'] = [[random.choice(TEMPLATES), random.choice(TEMPLATES)]
                                       for _ in range(random.randrange(0, 3))]
        if random.random() < .7:
            f['End_Stream'] = random.random() < .5
    elif t in ('data', 'datagram'):
        f['data_to_transfered'] = random.choice(TEMPLATES)
        if random.random() < .7:
            f['End_Stream'] = random.random() < .5
    elif t == 'sleep':
        f['Time_to_Stop'] = random.randrange(0, 5)
    return f

def rand_case(i):
    frames = [rand_frame() for _ in range(random.randrange(0, 5))]
    return {'name': 'c%d' % i, 'frames': frames,
            'expect': {'method': random.choice(['GET', 'POST', 'G-T']), 'target': '/a', 'host': 'h'}}

def rand_event(i):
    k = random.choice(['close', 'headers', 'data'])
    ev = {'at': random.randrange(0, 6), 'kind': k}
    if k != 'close':
        ev['stream'] = random.randrange(0, 9)
        ev['end'] = random.random() < .5
        if k == 'headers':
            ev['fields'] = [[random.choice(TEMPLATES), random.choice(TEMPLATES)]
                            for _ in range(random.randrange(0, 3))]
        else:
            ev['data'] = random.choice(TEMPLATES)
    return ev

CAPTURES = ["GET /a HTTP/1.1\r\nHost: h\r\n\r\n", "POST /b HTTP/1.1\r\nHost: h\r\nContent-Length: 3\r\n\r\nabc",
            "G\r\n", "GET /a HTTP/1.1\r\nHost: h\r\n", "", "0\r\n\r\n",
            "PATCH /c HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n2;xy\r\nhi\r\n0\r\nT: 1\r\n\r\n"]

def rand_channel(i, names):
    parts = []
    for j in range(random.randrange(0, 4)):
        owner = random.choice([None] + names)
        parts.append({'case': owner, 'data': random.choice(CAPTURES + TEMPLATES)})
    return {'name': 'z%d' % i, 'parts': parts}

results_ok = results_err = 0
for trial in range(400):
    ncases = random.randrange(0, 3)
    cases = [rand_case(i) for i in range(ncases)]
    names = [c['name'] for c in cases]
    events = [rand_event(i) for i in range(random.randrange(0, 4))]
    channels = [rand_channel(i, names) for i in range(random.randrange(0, 3))]
    doc = {'seed': random.choice(['s', '', 'S-e_1.9']), 'definitions': [], 'timeout_ms': random.randrange(1, 8),
           'cases': cases, 'events': events, 'channels': channels}
    raw = json.dumps(doc)
    out = run_raw(raw)
    if out == {'error': 'input'}:
        results_err += 1
    else:
        results_ok += 1
        assert set(out) == {'cases', 'channels'}, out
        assert len(out['cases']) == ncases
        for c in out['cases']:
            assert set(c) == {'name','stream','state','at','frames','request_frames','payload_bytes','sent',
                              'received','response_frames','response_body','origin_count','flags'}
            assert c['state'] in ('ok', 'timeout', 'closed', 'send_error')
            assert c['flags'] == sorted(set(c['flags']))
        for ch in out['channels']:
            assert set(ch) == {'name','bytes','requests','committed','error'}
            assert len(ch['committed']) == len(ch['requests']) or True
            for r in ch['requests']:
                assert set(r) == {'start','end','method','target','host','host_count','headers','body',
                                  'trailers','framing','owner','owners','flags'}
                assert r['flags'] == sorted(set(r['flags']))
                assert r['framing'] in ('none', 'length', 'chunked')
check('fuzz 400 random documents', True, '%d ok / %d err' % (results_ok, results_err))
print('   results ok: %d, err: %d' % (results_ok, results_err))

# random garbage bytes must also produce clean output
import os
for trial in range(100):
    garbage = bytes(random.randrange(256) for _ in range(random.randrange(0, 60)))
    p = subprocess.run(['python3', '-B', 'main.py'], input=garbage, capture_output=True, cwd='/workspace/project')
    assert p.returncode == 0, p.returncode
    json.loads(p.stdout)   # must parse
check('fuzz 100 garbage inputs', True)
summary()
